            "depends_on": ["V"],
            "support": ["S01", "材料首段"],
            "rules": ["lending-2020-12#13"],
            "supported_state": "题设套取银行信贷资金转贷事实支持A无效；低利率和乙不知情不排除该无效事由。"
          },
