          },
          {
            "id": "C_PRIORITY",
            "issue": "C各次付款的清偿顺序",
            "depends_on": ["C_PAYMENTS"],
            "support": ["S07", "S09"],
            "rules": ["civil-code-2020#561"],
            "supported_state": "T-02适用双方有效补充协议，本金优先；其余付款适用费用、利息、本金的法定顺序，乙单方备注不足以构成双方另有约定。"
          },
          {
            "id": "C_AMOUNT",
            "issue": "C未偿本金、利息及费用",
            "depends_on": ["C_PAYMENTS", "C_PRIORITY"],
            "support": ["S07", "S08", "S09", "S12", "材料首段"],
            "rules": [
              "lending-2020-12#25",
              "lending-2020-12#28",
              "civil-code-2020#561"
            ],
            "supported_state": "11.40%低于题设14.80%保护上限。以实际交付日、四次付款日、到期日及截日建立连续账本；各次清偿后的本金决定后续计息，未付利息不生利息，被偿本金在付款当日不再计息，已清偿费用不得重复请求。",
            "calculation_status": "可逐段计算；P1未进行最终金额求值或独立复算"
          },
          {
            "id": "J_PERIOD",
            "issue": "己的保证方式、期间及有效行权",
            "depends_on": ["V"],
            "support": ["S07", "S10"],
            "rules": [
              "civil-code-2020#686",
              "civil-code-2020#692",
              "civil-code-2020#693"
            ],
